                if not region_cells:
                    continue

                # Find the bounding box of the region
                min_r = min(rr for rr, cc in region_cells)
                max_r = max(rr for rr, cc in region_cells)
                min_c = min(cc for rr, cc in region_cells)
                max_c = max(cc for rr, cc in region_cells)

                # Apply the frame pattern to each cell in the region
                for (ur, uc) in region_cells:
                    # Check if cell is a corner
                    is_corner = (ur == min_r and uc == min_c) or \
                               (ur == min_r and uc == max_c) or \
                               (ur == max_r and uc == min_c) or \
                               (ur == max_r and uc == max_c)

                    # Check if cell is on the edge (but not corner)
                    is_edge = (ur == min_r or ur == max_r or uc == min_c or uc == max_c)

                    if is_corner:
                        output[ur][uc] = 1
                    elif is_edge:
                        output[ur][uc] = 4
                    else:
                        output[ur][uc] = 2

    return output
